def meetings_to_schedules(apps, schema_editor):
    """Each existing meeting keeps its date as its first schedule; accepted guests are assigned to it."""
    Meeting = apps.get_model('attendance', 'Meeting')
    MeetingSchedule = apps.get_model('attendance', 'MeetingSchedule')
    Participant = apps.get_model('attendance', 'Participant')
    for meeting in Meeting.objects.exclude(starts_at=None):
        schedule = MeetingSchedule.objects.create(meeting=meeting, starts_at=meeting.starts_at)
        Participant.objects.filter(origin_meeting=meeting, invitation_status='accepted').update(schedule=schedule)


